<?php use VazinCMS\Security;?><section class="title"><div><h1>مقصدهای سفر</h1><p>راهنمای شهرها را برای مخاطب ایرانی یا روسی مدیریت کنید.</p></div><a class="button secondary" href="/fa/destinations" target="_blank">پیش‌نمایش</a></section><?php if($error):?><div class="alert"><?=Security::e($error)?></div><?php endif;?><section class="panel"><h2>افزودن یا به‌روزرسانی مقصد</h2><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="form-grid"><label>کد مخاطب<input name="audience_code" maxlength="2" placeholder="IR" required></label><label>زبان<select name="locale"><option value="fa">فارسی</option><option value="ru">Русский</option></select></label><label>کشور<input name="country" required></label><label>شهر<input name="city" required></label><label>اولویت<input name="priority" type="number" value="100"></label></div><label>معرفی<textarea name="summary" rows="3"></textarea></label><label>شرایط ورود<textarea name="entry_notes" rows="2"></textarea></label><label>بودجه<textarea name="budget_notes" rows="2"></textarea></label><label>نکته محلی<textarea name="local_tip" rows="2"></textarea></label><button>ذخیره مقصد</button></form></section><section class="panel"><h2>مقصدهای منتشرشده</h2><div class="table"><table><thead><tr><th>مخاطب</th><th>زبان</th><th>کشور</th><th>شهر</th><th>معرفی</th><th></th></tr></thead><tbody><?php foreach($items as $r):?><tr><td><?=Security::e($r['audience_code'])?></td><td><?=Security::e($r['locale'])?></td><td><?=Security::e($r['country'])?></td><td><?=Security::e($r['city'])?></td><td><?=Security::e(mb_strimwidth($r['summary'],0,90,'…'))?></td><td><form method="post" data-confirm="حذف شود؟"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger">حذف</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
